// ---------- CONFIG ----------
const LABEL_NAME = 'Awaiting reply';
const NUDGE_AFTER_DAYS = 3;        // business etiquette: 2-4 days
const RENUDGE_AFTER_DAYS = 7;      // draft another nudge if still silent this long after the last one
const EXEC_NAME = 'Marvin';
const TZ = 'Asia/Manila';
// ----------------------------
return [{ json: { LABEL_NAME, NUDGE_AFTER_DAYS, RENUDGE_AFTER_DAYS, EXEC_NAME, TZ } }];

const cfg = $('Config').first().json;
const labels = $input.first().json.labels || [];
const label = labels.find(l => String(l.name).toLowerCase() === cfg.LABEL_NAME.toLowerCase());
if (!label) {
  throw new Error(`Gmail label "${cfg.LABEL_NAME}" not found. Create it in Gmail (Settings -> Labels -> Create new label) and add it to emails you're waiting on.`);
}
return [{ json: { labelId: label.id, labelName: label.name } }];

const cfg = $('Config').first().json;
const { labelId } = $('Resolve Label').first().json;
const state = $getWorkflowStaticData('global');
state.nudged = state.nudged || {};

const now = $now.toMillis();
const DAY = 86400000;
const header = (msg, name) => ((msg.payload && msg.payload.headers) || []).find(h => h.name.toLowerCase() === name.toLowerCase())?.value || '';
const firstName = (addr) => {
  const m = String(addr).match(/^\s*"?([^"<@,]+?)"?\s*</);
  const n = m ? m[1].trim() : String(addr).split('@')[0];
  return n.split(/[\s._-]+/)[0].replace(/^./, c => c.toUpperCase());
};

const out = [];
for (const item of $input.all()) {
  const t = item.json;
  const msgs = (t.messages || []).slice().sort((a, b) => Number(a.internalDate) - Number(b.internalDate));
  if (!msgs.length) continue;
  const last = msgs[msgs.length - 1];
  const lastIsMine = (last.labelIds || []).includes('SENT');
  const lastSentByMe = [...msgs].reverse().find(m => (m.labelIds || []).includes('SENT')) || last;
  const subject = header(msgs[0], 'Subject') || '(no subject)';
  const ageDays = Math.floor((now - Number(last.internalDate)) / DAY);
  const to = header(lastSentByMe, 'To');
  const base = { threadId: t.id, subject, ageDays, to, link: `https://mail.google.com/mail/u/0/#all/${t.id}`, labelId };

  if (!lastIsMine) {
    delete state.nudged[t.id];
    out.push({ json: { ...base, action: 'replied', from: header(last, 'From') } });
    continue;
  }
  const prev = state.nudged[t.id];
  const due = ageDays >= cfg.NUDGE_AFTER_DAYS &&
    (!prev || prev.lastMessageId !== last.id || (now - prev.at) >= cfg.RENUDGE_AFTER_DAYS * DAY);
  if (!due) {
    out.push({ json: { ...base, action: 'waiting', nudgedAlready: !!prev } });
    continue;
  }

  // Build a reply draft in the same thread (plain text, never sent automatically).
  const msgId = header(last, 'Message-ID');
  const refs = [header(last, 'References'), msgId].filter(Boolean).join(' ').trim();
  const body = [
    `Hi ${firstName(to)},`,
    '',
    `Just following up on my note below about "${subject.replace(/^(re|fwd?):\s*/i, '')}". Is there anything you need from me to move this forward?`,
    '',
    'Thanks,',
    cfg.EXEC_NAME,
  ].join('\r\n');
  const b64 = s => Buffer.from(s, 'utf8').toString('base64');
  const subj = /^re:/i.test(subject) ? subject : `Re: ${subject}`;
  const mime = [
    `To: ${to}`,
    header(lastSentByMe, 'Cc') ? `Cc: ${header(lastSentByMe, 'Cc')}` : null,
    `Subject: =?UTF-8?B?${b64(subj)}?=`,
    msgId ? `In-Reply-To: ${msgId}` : null,
    refs ? `References: ${refs}` : null,
    'MIME-Version: 1.0',
    'Content-Type: text/plain; charset="UTF-8"',
    'Content-Transfer-Encoding: base64',
  ].filter(Boolean).join('\r\n') + '\r\n\r\n' + b64(body);
  const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  state.nudged[t.id] = { lastMessageId: last.id, at: now };
  out.push({ json: { ...base, action: 'nudge', draftBody: { message: { raw, threadId: t.id } } } });
}
return out;

const cfg = $('Config').first().json;
const items = $('Classify Threads').all().map(i => i.json);
const esc = (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const line = t => `- <${t.link}|${esc(t.subject).slice(0, 90)}> - ${esc(t.to || t.from || '').slice(0, 60)} (${t.ageDays}d)`;
const group = a => items.filter(t => t.action === a);
const replied = group('replied'), nudged = group('nudge'), waiting = group('waiting');
if (!items.length) return [];

const sections = [];
if (nudged.length) sections.push(`*:envelope_with_arrow: Follow-up drafts ready (${nudged.length})* - review in Gmail Drafts\n` + nudged.map(line).join('\n'));
if (replied.length) sections.push(`*:white_check_mark: Replied - label cleared (${replied.length})*\n` + replied.map(line).join('\n'));
if (waiting.length) sections.push(`*:hourglass_flowing_sand: Still waiting (${waiting.length})*\n` + waiting.map(line).join('\n'));

const blocks = [{ type: 'header', text: { type: 'plain_text', text: `Follow-up tracker - ${$now.setZone(cfg.TZ).toFormat('ccc, LLL d')}` } }]
  .concat(sections.map(s => ({ type: 'section', text: { type: 'mrkdwn', text: s.slice(0, 2900) } })));
return [{ json: { blocks, text: `Follow-ups: ${nudged.length} drafted, ${replied.length} replied, ${waiting.length} waiting` } }];
